import RPi.GPIO as GPIO
import picamera
import time
import adafruit_circuitpython_mqtt
import adafruit_mqtt.client as mqtt

# Set up GPIO and MQTT
GPIO.setmode(GPIO.BCM)
GPIO.setup(17, GPIO.OUT)
mqtt_client = mqtt.Client()
mqtt_client.connect("mqtt.example.com", 1883, 60)

def on_connect(client, userdata, flags, rc):
    print(f"Connected with result code {rc}")
    client.subscribe("digital_input")

def on_message(client, userdata, message):
    print(f"Received message: {message.payload.decode('utf-8')}")
    digital_input = int(message.payload)
    GPIO.output(17, digital_input)

def main():
    while True:
        try:
            # Check if MQTT message is received
            if mqtt_client.connected:
                mqtt_client.subscribe("digital_input")
                while True:
                    try:
                        message = mqtt_client.loop_read()
                        on_message(mqtt_client, None, message)
                    except Exception as e:
                        print(f"Error: {e}")
                        break
            else:
                print("MQTT connection failed")
        except Exception as e:
            print(f"Error: {e}")

if __name__ == "__main__":
    main()
    GPIO.cleanup()

